const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const depok = ee.Geometry.Point([106.8186, -6.4025]); // Depok, Indonesia
  const region = depok.buffer(10000); // 10km buffer around Depok

  // Time periods - using similar months to avoid seasonal bias
  const start1990 = '1990-06-01';
  const end1990 = '1990-09-30';
  const start2019 = '2019-06-01';
  const end2019 = '2019-09-30';

  // 2. Data Acquisition - Landsat 5 for 1990, Landsat 8 for 2019
  function getL5Collection(startDate, endDate) {
    return ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
  }

  function getL8Collection(startDate, endDate) {
    return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
  }

  // Cloud masking function
  function maskLandsatClouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
    return image.updateMask(cloudMask.not());
  }

  // NDVI calculation
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Get collections
  const col1990 = getL5Collection(start1990, end1990).map(maskLandsatClouds).map(addNDVI);
  const col2019 = getL8Collection(start2019, end2019).map(maskLandsatClouds).map(addNDVI);

  // Check collection sizes
  const size1990 = col1990.size().getInfo();
  const size2019 = col2019.size().getInfo();

  console.log(`1990 Images: ${size1990}, 2019 Images: ${size2019}`);

  if (size1990 === 0 || size2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites
  const composite1990 = col1990.median().select('NDVI');
  const composite2019 = col2019.median().select('NDVI');

  // Check valid pixels
  const count1990 = composite1990.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2019 = composite2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid pixels 1990: ${count1990}, 2019: ${count2019}`);

  if (count1990 === 0 || count2019 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean NDVI
  const mean1990 = composite1990.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const mean2019 = composite2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Mean NDVI 1990: ${mean1990?.toFixed(3)}, 2019: ${mean2019?.toFixed(3)}`);

  // Validation
  if (mean1990 === null || mean2019 === null || 
      isNaN(mean1990) || isNaN(mean2019) ||
      mean1990 > 1 || mean2019 > 1 || 
      mean1990 < -1 || mean2019 < -1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (mean2019 < mean1990) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
